type CustomerStatus = "Aktif" | "Potansiyel" | "Pasif";
type SupplierStatus = "Aktif" | "Pasif";
type InvoiceStatus = "Taslak" | "Gönderildi" | "Ödendi" | "Vadesi Geçti";
type ExpenseStatus = "Bekliyor" | "Ödendi" | "Vadesi Geçti";
type ActivityKind = "customer" | "invoice" | "payment" | "expense" | "supplier" | "bank" | "sale" | "system";
type AppSection = "Dashboard" | "Gün Planı" | "Otomasyonlar" | "ERP" | "Belgeler" | "Müşteriler" | "Randevular" | "Faturalar" | "Giderler" | "Tedarikçiler" | "Bankalar" | "Satışlar" | "Raporlar" | "Fatura Önizleme";

type Customer = { id: string; name: string; role: string; email: string; phone: string; status: CustomerStatus; note: string };
type Supplier = { id: string; name: string; category: string; email: string; phone: string; taxNumber: string; paymentTerm: string; status: SupplierStatus; note: string };
type InvoiceLine = { id: string; description: string; quantity: number; unitPrice: number; vatRate: number };
type Invoice = { id: string; number: string; customerId: string; title: string; amount: number; issueDate: string; dueDate: string; status: InvoiceStatus; paymentNote?: string; lineItems?: InvoiceLine[] };
type Expense = { id: string; number: string; supplierId: string; title: string; category: string; amount: number; expenseDate: string; dueDate: string; status: ExpenseStatus; paymentMethod: string; documentNumber: string; note: string };
type BankAccount = { id: string; name: string; bank: string; type: string; ibanLast4: string; balance: number; ledgerBalance: number; lastSync: string; color: "blue" | "emerald" | "violet" };
type BankTransaction = { id: string; accountId: string; date: string; description: string; counterparty: string; direction: "Gelen" | "Giden"; amount: number; category: string; status: "Bekliyor" | "Eşleşti" | "İncelenmeli"; reference?: string };
type SaleStatus = "Teklif" | "Onaylandı" | "Faturalandı" | "Tahsil Edildi";
type Sale = { id: string; number: string; customerId: string; title: string; amount: number; createdAt: string; expectedClose: string; status: SaleStatus; probability: number; invoiceNumber?: string };
type JournalLine = { id: string; accountCode: string; accountName: string; debit: number; credit: number };
type JournalEntry = { id: string; number: string; date: string; description: string; source: "Fatura" | "Gider" | "Banka" | "Manuel"; reference?: string; status: "İşlendi" | "Taslak"; lines: JournalLine[] };
type AccountType = "Varlık" | "Yükümlülük" | "Gelir" | "Gider" | "Özkaynak";
type ChartAccount = { id: string; code: string; name: string; type: AccountType; group: string; normalBalance: "Borç" | "Alacak"; active: boolean };
type ArchiveItem = { id: string; type: "Fatura" | "Gider" | "Satış" | "Banka"; reference: string; title: string; date: string; amount: number; reason: string; source: "Faturalar" | "Giderler" | "Satışlar" | "Bankalar"; archived: boolean };
type ActivityItem = { id: string; kind: ActivityKind; title: string; description: string; timestamp: string };
type DemoData = { customers: Customer[]; suppliers: Supplier[]; invoices: Invoice[]; expenses: Expense[]; bankAccounts: BankAccount[]; bankTransactions: BankTransaction[]; sales: Sale[]; journalEntries: JournalEntry[]; chartAccounts: ChartAccount[]; archiveItems: ArchiveItem[]; plannerTasks: PlannerTask[]; appointments: Appointment[]; automationRules: AutomationRule[]; catalogItems: CatalogItem[]; settings: CompanySettings; activities: ActivityItem[] };
type NavItem = { label: string; icon: typeof LayoutDashboard; count?: string };
type DeleteTarget = { kind: "customer" | "invoice" | "expense" | "supplier"; id: string; label: string } | null;

