function loadData(): DemoData {
  const defaults = initialData();
  if (typeof window === "undefined") return defaults;
  try {
    const parsed = JSON.parse(window.localStorage.getItem(storageKey) || "null") as Partial<DemoData> | null;
    if (!parsed) return defaults;
    return {
      customers: Array.isArray(parsed.customers) ? parsed.customers : defaults.customers,
      suppliers: Array.isArray(parsed.suppliers) ? parsed.suppliers : defaults.suppliers,
      invoices: Array.isArray(parsed.invoices) ? parsed.invoices : defaults.invoices,
      expenses: Array.isArray(parsed.expenses) ? parsed.expenses : defaults.expenses,
      bankAccounts: Array.isArray(parsed.bankAccounts) ? parsed.bankAccounts : defaults.bankAccounts,
      bankTransactions: Array.isArray(parsed.bankTransactions) ? parsed.bankTransactions : defaults.bankTransactions,
      sales: Array.isArray(parsed.sales) ? parsed.sales : defaults.sales,
      journalEntries: Array.isArray(parsed.journalEntries) ? parsed.journalEntries : defaults.journalEntries,
      chartAccounts: Array.isArray(parsed.chartAccounts) ? parsed.chartAccounts : defaults.chartAccounts,
      archiveItems: Array.isArray(parsed.archiveItems) ? parsed.archiveItems : defaults.archiveItems,
      plannerTasks: Array.isArray(parsed.plannerTasks) ? parsed.plannerTasks : defaults.plannerTasks,
      appointments: Array.isArray(parsed.appointments) ? parsed.appointments : defaults.appointments,
      automationRules: Array.isArray(parsed.automationRules) ? parsed.automationRules : defaults.automationRules,
      catalogItems: Array.isArray(parsed.catalogItems) ? parsed.catalogItems : defaults.catalogItems,
      settings: parsed.settings && typeof parsed.settings === "object" ? { ...defaults.settings, ...parsed.settings as Partial<CompanySettings> } : defaults.settings,
      activities: Array.isArray(parsed.activities) ? parsed.activities : defaults.activities,
    };
  } catch { return defaults; }
}

