const dateText = (value: string) => new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(`${value}T12:00:00`));
const nowText = () => new Intl.DateTimeFormat("tr-TR", { dateStyle: "medium", timeStyle: "short" }).format(new Date());
const makeActivity = (kind: ActivityKind, title: string, description: string): ActivityItem => ({ id: `act-${Date.now()}`, kind, title, description, timestamp: nowText() });
