function invoiceTotals(invoice: Invoice) {
  const lineItems = invoice.lineItems?.length ? invoice.lineItems : [{ id: "derived", description: invoice.title, quantity: 1, unitPrice: invoice.amount / 1.2, vatRate: 20 }];
  const net = lineItems.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0);
  const tax = lineItems.reduce((sum, item) => sum + item.quantity * item.unitPrice * item.vatRate / 100, 0);
  return { lineItems, net, tax, total: net + tax };
}

