  return <>{mobileOpen && <button aria-label="Menüyü kapat" onClick={() => setMobileOpen(false)} className="fixed inset-0 z-30 bg-slate-900/25 lg:hidden" />}<aside className={`dashboard-sidebar fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col overscroll-contain overflow-y-auto border-r px-3 py-4 transition-transform lg:sticky lg:top-0 lg:h-screen lg:shrink-0 lg:translate-x-0 ${mobileOpen ? "translate-x-0" : "-translate-x-full"}`}><div className="mb-7 flex items-center justify-between px-2"><BrandMark /><button onClick={() => setMobileOpen(false)} className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 lg:hidden"><X className="h-4 w-4" /></button></div><nav className="space-y-1">{primaryNavigation.map(navLink)}</nav><section className="mt-6">{groupHeading("Finans")}<nav className="space-y-1">{financeNavigation.map(navLink)}</nav></section><section className="mt-6">{groupHeading("CRM")}<nav className="space-y-1">{crmNavigation.map(navLink)}</nav></section><div className="my-5 border-t border-slate-200/70" /><nav className="space-y-1">{managementNavigation.map(navLink)}<button onClick={() => toast.info("Bildirim Merkezi", { description: "Ödeme ve vade hareketleri aktivite günlüğünde görünür." })} className="flex h-9 w-full items-center gap-3 rounded-lg px-3 text-[12px] font-semibold text-slate-600 transition hover:bg-slate-100/80 hover:text-slate-900"><Bell className="h-4 w-4 text-slate-400" />Bildirimler</button></nav><div className="mt-auto border-t border-slate-200/70 pt-4"><button onClick={onLogout} className="flex h-9 w-full items-center gap-3 rounded-lg px-3 text-[12px] font-semibold text-slate-600 transition hover:bg-slate-100/80 hover:text-slate-900"><LogOut className="h-4 w-4 text-slate-400" />Çıkış Yap</button></div></aside></>;
