  const deleteAppointment = (id: string) => { const appointment = (data.appointments ?? []).find((item) => item.id === id); setData((current) => addActivity({ ...current, appointments: (current.appointments ?? []).filter((item) => item.id !== id) }, makeActivity("system", "Görüşme takvimden kaldırıldı", appointment ? `${appointment.title} görüşmesi CRM takviminden silindi.` : "Görüşme CRM takviminden silindi."))); };
