  const confirmDelete = () => { if (!deleteTarget) return; setData((current) => { if (deleteTarget.kind === "supplier") return current; if (deleteTarget.kind === "customer") { const removed = current.invoices.filter((invoice) => invoice.customerId === deleteTarget.id).length; return addActivity({ ...current, customers: current.customers.filter((item) => item.id !== deleteTarget.id), invoices: current.invoices.filter((invoice) => invoice.customerId !== deleteTarget.id) }, makeActivity("customer", `${deleteTarget.label} silindi`, removed ? `Müşteriyle ilişkili ${removed} fatura da kaldırıldı.` : "Müşteri kaydı kaldırıldı.")); } if (deleteTarget.kind === "invoice") return addActivity({ ...current, invoices: current.invoices.filter((item) => item.id !== deleteTarget.id) }, makeActivity("invoice", `${deleteTarget.label} silindi`, "Fatura kaydı ve ilgili tahsilat göstergesi kaldırıldı.")); return addActivity({ ...current, expenses: current.expenses.filter((item) => item.id !== deleteTarget.id) }, makeActivity("expense", `${deleteTarget.label} silindi`, "Gider kaydı ve ilgili ödeme göstergesi kaldırıldı.")); }); toast.success(deleteTarget.kind === "expense" ? "Gider silindi" : deleteTarget.kind === "invoice" ? "Fatura silindi" : "Müşteri silindi"); setDeleteTarget(null); };
